148     template<qualifier Q>
149     struct compute_to_string<vec<1, bool, Q> >
150     {
151         GLM_FUNC_QUALIFIER static std::string call(vec<1, bool, Q> const& x)
152         {
153             return detail::format("bvec1(%s)",
154                 x[0] ? detail::LabelTrue : detail::LabelFalse);
155         }
156     };
