194     template<typename T, qualifier Q>
195     struct compute_to_string<vec<1, T, Q> >
196     {
197         GLM_FUNC_QUALIFIER static std::string call(vec<1, T, Q> const& x)
198         {
199             char const * PrefixStr = prefix<T>::value();
200             char const * LiteralStr = literal<T, std::numeric_limits<T>::is_iec559>::value();
201             std::string FormatStr(detail::format("%svec1(%s)",
202                 PrefixStr,
203                 LiteralStr));
204 
205             return detail::format(FormatStr.c_str(),
206                 static_cast<typename cast<T>::value_type>(x[0]));
207         }
208     };
