446     template<typename T, qualifier Q>
447     struct compute_to_string<qua<T, Q> >
448     {
449         GLM_FUNC_QUALIFIER static std::string call(qua<T, Q> const& q)
450         {
451             char const * PrefixStr = prefix<T>::value();
452             char const * LiteralStr = literal<T, std::numeric_limits<T>::is_iec559>::value();
453             std::string FormatStr(detail::format("%squat(%s, {%s, %s, %s})",
454                 PrefixStr,
455                 LiteralStr, LiteralStr, LiteralStr, LiteralStr));
456 
457             return detail::format(FormatStr.c_str(),
458                 static_cast<typename cast<T>::value_type>(q.w),
459                 static_cast<typename cast<T>::value_type>(q.x),
460                 static_cast<typename cast<T>::value_type>(q.y),
461                 static_cast<typename cast<T>::value_type>(q.z));
462         }
463     };
