478                 static_cast<typename cast<T>::value_type>(x.real.w),
479                 static_cast<typename cast<T>::value_type>(x.real.x),
480                 static_cast<typename cast<T>::value_type>(x.real.y),
481                 static_cast<typename cast<T>::value_type>(x.real.z),
482                 static_cast<typename cast<T>::value_type>(x.dual.w),
483                 static_cast<typename cast<T>::value_type>(x.dual.x),
